from typing import List

class Fenwick:
    __slots__ = ("n", "bit")
    def __init__(self, n: int):
        self.n = n
        self.bit = [0] * (n + 1)

    def update(self, idx: int, val: int) -> None:
        bit = self.bit
        n = self.n
        while idx <= n:
            if val > bit[idx]:
                bit[idx] = val
            idx += idx & -idx

    def query(self, idx: int) -> int:
        res = 0
        bit = self.bit
        while idx:
            if bit[idx] > res:
                res = bit[idx]
            idx -= idx & -idx
        return res


class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0

        MAX_VAL = 300
        MAX_DIFF = MAX_VAL          # maximum possible absolute difference (<=299, we use 300 for safety)
        size = MAX_DIFF + 1         # 301

        # Fenwick tree for each possible value (1..300)
        fenwick = [Fenwick(size) for _ in range(MAX_VAL + 1)]

        seen = [False] * (MAX_VAL + 1)
        seen_vals = []

        ans = 1

        for v in nums:
            fenwick_v = fenwick[v]
            for u in seen_vals:
                d = v - u
                if d < 0:
                    d = -d
                idx = size - d
                best = fenwick[u].query(idx)
                if best > 0:
                    cand = best + 1
                else:
                    cand = 2  # start a new subsequence of length 2
                if cand > ans:
                    ans = cand
                fenwick_v.update(idx, cand)

            if not seen[v]:
                seen[v] = True
                seen_vals.append(v)

        return ans
