import sys

def solve():
    input = sys.stdin.readline
    HWD = input().split()
    if not HWD:
        return
    H, W, D = map(int, HWD)
    grid = [input().strip() for _ in range(H)]
    floors = []
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.':
                floors.append((i, j))
    N = len(floors)
    masks = []
    for idx, (x, y) in enumerate(floors):
        mask = 0
        for jdx, (x2, y2) in enumerate(floors):
            if abs(x - x2) + abs(y - y2) <= D:
                mask |= 1 << jdx
        masks.append(mask)
    max_hum = 0
    for i in range(N):
        for j in range(i + 1, N):
            union_mask = masks[i] | masks[j]
            cnt = bin(union_mask).count('1')
            if cnt > max_hum:
                max_hum = cnt
    print(max_hum)

if __name__ == "__main__":
    solve()
