def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    INF = M + 1
    minR = [INF] * (M + 2)  # 1-indexed; index 0 unused
    for _ in range(N):
        L = int(next(it))
        R = int(next(it))
        if R < minR[L]:
            minR[L] = R
    # suffix minimum to get minimal R among intervals with L >= l
    for l in range(M, 0, -1):
        if minR[l+1] < minR[l]:
            minR[l] = minR[l+1]
    ans = 0
    for l in range(1, M + 1):
        diff = minR[l] - l
        if diff > 0:
            ans += diff
    print(ans)

if __name__ == "__main__":
    solve()
