import sys

def solve() -> None:
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    a = [int(next(it)) for _ in range(n)]

    ans = 0
    for parity in (0, 1):
        pos = []
        for i in range(n - 1):
            if (i & 1) == parity and a[i] == a[i + 1]:
                pos.append(i)

        left = 0
        mp = {}
        for right in range(len(pos)):
            if right > left and pos[right] != pos[right - 1] + 2:
                left = right
                mp.clear()
            val = a[pos[right]]
            if val in mp:
                prev = mp[val]
                if prev >= left:
                    left = prev + 1
                mp.pop(val)
            mp[val] = right
            cur_len = right - left + 1
            ans = max(ans, 2 * cur_len)

    print(ans)

if __name__ == "__main__":
    solve()
